#!/usr/bin/env node

// Bundles the CommonJS `packageurl-js` package into a single classic script
// that exposes a global `PackageURL`, for pages that load libraries with a
// plain <script src> tag and have no bundler in the toolchain.
//
// Upstream ships CommonJS only (no UMD/ESM/browser build) and is not on cdnjs.
// Drop this script and the generated file once upstream publishes a browser
// build: https://github.com/package-url/packageurl-js/issues

const fs = require('fs');
const path = require('path');

const repoRoot = path.resolve(__dirname, '..');
const packageArg = process.argv[2] || 'node_modules/packageurl-js';
const outputArg = process.argv[3] || 'public/js/packageurl-js.js';
const packageRoot = path.resolve(repoRoot, packageArg);
const outputPath = path.resolve(repoRoot, outputArg);

const globalName = 'PackageURL';
const requirePattern = /require\(\s*(['"])(\.[^'"]*)\1\s*\)/g;

const seen = new Set();
const ordered = [];

// Node's resolution rules, limited to what this package actually uses:
// relative ids, with an implicit `.js` extension.
function resolveModuleId(fromId, specifier) {
    if (!specifier.startsWith('.')) {
        throw new Error('Only relative requires are supported: ' + specifier);
    }

    let resolved = path.resolve(path.dirname(path.join(packageRoot, fromId)), specifier);
    if (!fs.existsSync(resolved) && !path.extname(resolved)) {
        resolved = resolved + '.js';
    }
    if (!fs.existsSync(resolved)) {
        throw new Error('Cannot resolve ' + specifier + ' from ' + fromId);
    }

    return path.relative(packageRoot, resolved).split(path.sep).join('/');
}

function collectModules(moduleId) {
    if (seen.has(moduleId)) {
        return;
    }
    seen.add(moduleId);

    const absolute = path.join(packageRoot, moduleId);
    let source = fs.readFileSync(absolute, 'utf8');

    if (moduleId.endsWith('.json')) {
        // JSON modules become a plain assignment; nothing to walk.
        ordered.push({
            moduleId: moduleId,
            source: 'module.exports = ' + source.trim() + ';'
        });
        return;
    }

    // Rewrite relative requires to resolved ids first, so the runtime shim
    // does not have to resolve paths itself.
    source = source.replace(requirePattern, function (match, quote, specifier) {
        const dep = resolveModuleId(moduleId, specifier);
        collectModules(dep);
        return 'require(' + JSON.stringify(dep) + ')';
    });

    ordered.push({
        moduleId: moduleId,
        source: source
    });
}

function ensureParentDir(filePath) {
    const dirPath = path.dirname(filePath);
    if (!fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
    }
}

const packageJson = require(path.join(packageRoot, 'package.json'));
const entryId = packageJson.main || 'index.js';
collectModules(entryId);

// `/*!` keeps minifiers from stripping the attribution.
const banner = '/*!\n' +
    ' * ' + packageJson.homepage + '\n' +
    ' * ' + packageJson.name + ' version: ' + packageJson.version + '\n' +
    ' * (c) ' + packageJson.author + '\n' +
    ' * ' + packageJson.license + ' license\n' +
    ' *\n' +
    ' * Generated by scripts/bundle-purl.js - do not edit.\n' +
    ' */\n';

const modules = ordered
    .map(function (moduleInfo) {
        return '    __modules[' + JSON.stringify(moduleInfo.moduleId) + '] = ' +
            'function (module, exports, require) {\n' +
            moduleInfo.source.replace(/\s+$/, '') + '\n' +
            '    };';
    })
    .join('\n\n');

const output = banner +
    'var ' + globalName + ' = (function () {\n' +
    '    var __modules = {};\n' +
    '    var __cache = {};\n' +
    '\n' +
    '    function require(id) {\n' +
    '        if (__cache[id]) {\n' +
    '            return __cache[id].exports;\n' +
    '        }\n' +
    '        var module = { exports: {} };\n' +
    '        __cache[id] = module;\n' +
    '        __modules[id](module, module.exports, require);\n' +
    '        return module.exports;\n' +
    '    }\n' +
    '\n' +
    modules + '\n' +
    '\n' +
    '    return require(' + JSON.stringify(entryId) + ').' + globalName + ';\n' +
    '})();\n';

ensureParentDir(outputPath);
fs.writeFileSync(outputPath, output);
process.stdout.write(
    'Bundled ' + ordered.length + ' module(s) of ' + packageArg + ' into ' +
    path.relative(repoRoot, outputPath) + '\n'
);
